L(OA10, 4,
  "Una pelota blanda, 4 conos, un espacio de 8 × 4 m, papel y lápiz, 4 a 6 personas y un adulto cerca.",
  "Aprenderé a reparar una falta y a reanudar el juego con respeto. Sirve para resolver conflictos sin pelear.",
  ["Sé decir la verdad cuando me equivoco.", "Sé qué es una ventaja injusta."],
  ["Una falta es romper una regla. Todos podemos cometerla, a veces sin querer. Lo importante es qué haces después. Reparar es hacerte cargo del problema: reconoces la falta, pides disculpas con palabras sinceras y propones cómo arreglarlo. Por ejemplo: «Te empujé sin querer, lo siento. ¿Estás bien? Repitamos la jugada».",
   "Reanudar es volver a empezar el juego después de la falta. Se hace con una señal clara: el árbitro dice «seguimos», y el juego continúa con un pase o con la jugada repetida. Antes de reanudar, comprueba que la persona afectada esté bien. Si se lastimó, se detiene el juego y se avisa a un adulto.",
   "Quien recibe las disculpas puede aceptarlas o pedir un momento. Nadie debe ser obligado a perdonar de inmediato. El juego limpio incluye cuidar a quien se afectó y a quien se equivocó. Cuando todos reparan, el grupo aprende y se confía más. Un conflicto serio se lleva a un adulto."],
  [("falta", "romper una regla del juego"), ("reparar", "hacerse cargo del problema y arreglarlo"), ("disculpa", "palabras sinceras para reconocer un error"), ("reanudar", "volver a empezar el juego"), ("señal", "aviso claro para detener o seguir")],
  [("Pedir disculpas", "Empujaste sin querer a un compañero. ¿Qué dices?", ["Reconozco la falta.", "Pregunto si está bien.", "Digo «lo siento» y propongo repetir."], "Reconocer la falta, preguntar si está bien y proponer repetir"),
   ("Reanudar", "Después de una falta, todos aceptaron las disculpas. ¿Qué hace falta para seguir?", ["Necesito comprobar que todos estén bien.", "Necesito una señal clara.", "El árbitro dice «seguimos» y se repite la jugada."], "Una señal clara del árbitro y repetir la jugada")],
  [("Decir «no fue mi culpa» y no reparar.", "Se queda el problema.", "Reconoce y repara."), ("Obligar a perdonar de inmediato.", "Cada uno necesita su tiempo.", "Respeta el tiempo de la otra persona.")],
  [ex("Romper una regla del juego, ¿es una falta o un acuerdo?", "Una falta", "Rompe la regla."),
   ex("Pedir disculpas sinceras, ¿es reparar o ignorar?", "Reparar", "Te haces cargo."),
   ex("Para volver a empezar, ¿hace falta una señal clara o empezar a escondidas?", "Una señal clara", "Todos deben saberlo.")],
  [ex("Empujas sin querer y el otro cae. ¿Primero preguntas si está bien o sigues jugando?", "Preguntas si está bien", "Cuidar a la persona es lo primero."),
   ex("Alguien se lastimó. ¿Se reanuda el juego o se avisa a un adulto?", "Se avisa a un adulto", "La seguridad va primero."),
   ex("El afectado pide un momento antes de aceptar las disculpas. ¿Se lo das?", "Sí", "Cada persona necesita su tiempo.")],
  [arith("Hubo 3 faltas en el juego y cada reparación duró 30 segundos. ¿Cuántos segundos se usaron en reparar?", "3*30", "Se multiplican las faltas por los segundos.", " segundos"),
   arith("Jugaron 10 minutos y 2 minutos fueron de reparaciones. ¿Cuántos minutos jugaron de verdad?", "10-2", "Se restan los minutos de reparación.", " minutos"),
   arith("En 2 partidos hubo 2 y 1 faltas. ¿Cuántas faltas hubo en total?", "2+1", "Se suman las faltas de los dos partidos.", " faltas")],
  [ex("Ema se disculpó y propuso repetir la jugada. Fede dijo «no fue mi culpa». ¿Quién reparó la falta?", "Ema", "Reconoció y propuso arreglar."),
   ex("Gina dice: «Si pido disculpas, ya no tengo que hacer nada más». ¿Es siempre así?", "No", "A veces hay que reparar con una acción, como repetir la jugada.")],
  [ex("En un partido uno de ustedes se enoja y quiere pelear. ¿Qué haces: A) lo apoyas, B) pides una pausa y a un adulto?", "B", "Una pausa evita conflictos mayores.")],
  [ex("En Educación Física: ¿Qué es reparar una falta?", "Hacerse cargo y arreglar el problema", "Incluye pedir disculpas."),
   ex("¿Qué se comprueba antes de reanudar?", "Que todos estén bien", "Se cuida a las personas."),
   arith("Hubo 5 faltas y repararon 3. ¿Cuántas quedaron sin reparar?", "5-3", "Se restan las reparadas.", " faltas")],
  ("En un juego de 4 a 6 personas con una pelota blanda, representen una falta sin contacto (por ejemplo, empezar antes de la señal), sin tocarse. Practiquen 3 formas de reparar con palabras sinceras y una señal para reanudar. Anoten cuántos segundos dura cada reparación y cuántos en total.",
   "Reparación 1: 20 segundos. Reparación 2: 30. Reparación 3: 25. En total 75 segundos. Siempre preguntamos si estaba bien y dijimos «seguimos».",
   ["reconoce la falta", "pregunta si está bien", "usa una señal para reanudar"],
   ["tabla de tiempos", "observación de un adulto", "relato oral"],
   ["no reparar", "obligar a perdonar", "ocultar lesiones"],
   "Reconoce las disculpas sinceras y pide agregar una acción de reparación."),
  "Practica una disculpa sincera de una frase.",
  "Escribe un guion de 3 frases para reparar una falta en un juego.")
